export const governanceAuthorityAudit = pgTable("governance_authority_audit", {
  id: serial("id").primaryKey(),
  /** Surface type that triggered governance (medical, financial, legal, marketing, etc.) */
  surfaceType: varchar("surface_type", { length: 64 }).notNull(),
  /** Whether the surface is regulated (medical, financial, legal) */
  regulated: boolean("regulated").notNull().default(false),
  /** Whether external Gravito was attempted */
  externalAttempted: boolean("external_attempted").notNull().default(false),
  /** Whether external Gravito succeeded */
  externalSuccess: boolean("external_success").notNull().default(false),
  /** External Gravito source (external_gravito, circuit_breaker_open, timeout, etc.) */
  externalSource: varchar("external_source", { length: 64 }).notNull().default("not_attempted"),
  /** External Gravito latency in ms */
  externalLatencyMs: integer("external_latency_ms").notNull().default(0),
  /** Internal Gravito latency in ms */
  internalLatencyMs: integer("internal_latency_ms").notNull().default(0),
  /** Total latency including both calls in ms */
  totalLatencyMs: integer("total_latency_ms").notNull().default(0),
  /** Merge strategy used (most_conservative, external_authority, internal_fallback, etc.) */
  mergeStrategy: varchar("merge_strategy", { length: 64 }).notNull(),
  /** Authority source that made the final decision */
  authoritySource: varchar("authority_source", { length: 64 }).notNull(),
  /** Final governance score (0-100) */
  finalScore: integer("final_score").notNull().default(0),
  /** Whether content was approved for release */
  finalApproved: boolean("final_approved").notNull().default(false),
  /** Final severity level */
  finalSeverity: varchar("final_severity", { length: 32 }).notNull().default("pass"),
  /** Number of issues found */
  issueCount: integer("issue_count").notNull().default(0),
  /** Number of patches suggested */
  patchCount: integer("patch_count").notNull().default(0),
  /** Gravito run ID for cross-referencing */
  gravitoRunId: varchar("gravito_run_id", { length: 256 }).notNull(),
  /** Retry count before success/failure */
  retryCount: integer("retry_count").notNull().default(0),
  /** Circuit breaker state at time of decision */
  circuitBreakerState: varchar("circuit_breaker_state", { length: 32 }).notNull().default("closed"),
  /** Timestamp (UTC ms since epoch) */
  createdAt: bigint("created_at", { mode: "number" }).notNull(),
}, (table) => [
  index("idx_gov_audit_surface").on(table.surfaceType),
  index("idx_gov_audit_created").on(table.createdAt),
  index("idx_gov_audit_merge_strategy").on(table.mergeStrategy),
  index("idx_gov_audit_authority_source").on(table.authoritySource),
  index("idx_gov_audit_regulated").on(table.regulated),
  index("idx_gov_audit_external_success").on(table.externalSuccess),
  index("idx_gov_audit_gravito_run").on(table.gravitoRunId),
]);

export type GovernanceAuthorityAuditRow = typeof governanceAuthorityAudit.$inferSelect;
export type InsertGovernanceAuthorityAuditRow = typeof governanceAuthorityAudit.$inferInsert;

