    surfaceType: z.string().optional(),
    regulated: z.boolean().optional(),
  }).optional())
  .query(async ({ input }) => {
    const opts = input || { days: 7, limit: 50 };

    // Get authority layer metrics
    const authorityMetrics = getAuthorityMetrics();
    const authorityHealth = getAuthorityLayerHealth();

    // Get inline client metrics
    const inlineMetrics = getInlineMetrics();
    const breakerState = getCircuitBreakerState();
    const uptimeMetrics = getGovernanceUptimeMetrics();

    // Get in-memory audit trail (fast)
    const memoryAuditTrail = getAuthorityAuditSummary();

    // Get database-backed stats (durable)
    const dbStats = await getAuthorityAuditStats(opts.days);

    // Get recent audit entries from database
    const sinceTimestamp = Date.now() - (opts.days * 24 * 60 * 60 * 1000);
    const recentEntries = await getAuthorityAuditEntries({
      limit: opts.limit,
      surfaceType: opts.surfaceType,
      regulated: opts.regulated,
      sinceTimestamp,
    });

    return {
      // Summary statistics
      summary: {
        totalDecisions: dbStats.totalDecisions,
        externalSuccessRate: Math.round(dbStats.externalSuccessRate * 10000) / 100,
        avgLatencyMs: dbStats.avgLatencyMs,
        regulatedDecisions: dbStats.regulatedDecisions,
        blockedDecisions: dbStats.blockedDecisions,
        mergeStrategyCounts: dbStats.mergeStrategyCounts,
        periodDays: opts.days,
      },

      // Authority layer state
      authorityLayer: {
        enabled: authorityHealth.enabled,
        externalReachable: authorityHealth.externalReachable,
        internalReachable: authorityHealth.internalReachable,
        metrics: {
          externalSuccesses: authorityMetrics.externalSuccesses,
          externalFailures: authorityMetrics.externalFailures,
          internalFallbacks: authorityMetrics.internalFallbacks,
          failClosedEvents: authorityMetrics.failClosedEvents,
          mergedDecisions: authorityMetrics.mergedDecisions,
        },
      },

      // Inline client state
      inlineClient: {
        circuitBreakerState: breakerState,
        totalCalls: inlineMetrics.totalCalls,
        successRate: inlineMetrics.successRate,
        avgLatencyMs: inlineMetrics.avgLatencyMs,
        uptime: uptimeMetrics,
      },

      // In-memory audit summary
      memoryAudit: memoryAuditTrail,

      // Recent database entries
      recentEntries: recentEntries.map((entry: AuthorityAuditEntry) => ({
        id: entry.id,
        surfaceType: entry.surfaceType,
        regulated: entry.regulated,
        externalAttempted: entry.externalAttempted,
        externalSuccess: entry.externalSuccess,
        mergeStrategy: entry.mergeStrategy,
        finalApproved: entry.finalApproved,
        finalSeverity: entry.finalSeverity,
        totalLatencyMs: entry.totalLatencyMs,
        createdAt: entry.createdAt,
      })),
    };
  });

// ============================================================================
// PANEL 3: REGULATED FLOW
// ============================================================================

const regulatedFlowProcedure = adminProcedure.query(async () => {
  const preApprovalMetrics = getPreApprovalMetrics();
  const authorityMetrics = getAuthorityMetrics();

  // Get regulated-only audit entries from DB
  const regulatedEntries = await getAuthorityAuditEntries({
    regulated: true,
    limit: 50,
    sinceTimestamp: Date.now() - (7 * 24 * 60 * 60 * 1000),
  });

  return {
    // Pre-approval metrics
    preApproval: {
      requested: preApprovalMetrics.preApprovalsRequested,
      granted: preApprovalMetrics.preApprovalsGranted,
      denied: preApprovalMetrics.preApprovalsDenied,
      failClosed: preApprovalMetrics.failClosedEvents,
      approvalRate: preApprovalMetrics.preApprovalsRequested > 0
        ? Math.round((preApprovalMetrics.preApprovalsGranted / preApprovalMetrics.preApprovalsRequested) * 10000) / 100
        : 0,
    },

    // Regulated review metrics
    regulatedReviews: {
      attempted: preApprovalMetrics.regulatedReviewsAttempted,
      blocked: preApprovalMetrics.regulatedReviewsBlocked,
      blockRate: preApprovalMetrics.regulatedReviewsAttempted > 0
        ? Math.round((preApprovalMetrics.regulatedReviewsBlocked / preApprovalMetrics.regulatedReviewsAttempted) * 10000) / 100
        : 0,
    },

    // Header injection stats
    headerInjection: {
      totalInjected: preApprovalMetrics.headersInjected,
      schemaNormalizations: preApprovalMetrics.schemaNormalizations,
    },

    // Authority layer fail-closed events
    failClosed: {
      total: authorityMetrics.failClosedEvents,
      description: 'Regulated content blocked because external Gravito was unavailable',
    },

    // Regulated surface types
    regulatedSurfaces: Array.from(REGULATED_SURFACES),

    // Recent regulated decisions
    recentRegulatedDecisions: regulatedEntries.map((entry: AuthorityAuditEntry) => ({
      id: entry.id,
      surfaceType: entry.surfaceType,
      externalAttempted: entry.externalAttempted,
      externalSuccess: entry.externalSuccess,
      mergeStrategy: entry.mergeStrategy,
      finalApproved: entry.finalApproved,
      finalSeverity: entry.finalSeverity,
      totalLatencyMs: entry.totalLatencyMs,
      createdAt: entry.createdAt,
    })),
  };
});

// ============================================================================
// PROMETHEUS EXPORT
// ============================================================================

const prometheusExportProcedure = adminProcedure.query(() => {
  return {
    metrics: exportPrometheusMetrics(),
    timestamp: Date.now(),
  };
});

// ============================================================================
// COMBINED OVERVIEW (all 3 panels in one call)
// ============================================================================

const overviewProcedure = adminProcedure
  .input(z.object({
    days: z.number().min(1).max(90).default(7),
  }).optional())
  .query(async ({ input }) => {
    const days = input?.days || 7;

    // Gather all data in parallel
    const [
      transportStatus,
      transportMetrics,
      externalHealth,
      syncMetrics,
      authorityMetrics,
      authorityHealth,
      preApprovalMetrics,
      dbStats,
      recentEntries,
    ] = await Promise.all([
      Promise.resolve(getExternalTransportStatus()),
      Promise.resolve(getTransportMetrics()),
      Promise.resolve(getExternalGravitoHealth()),
      Promise.resolve(getSyncWrapperMetrics()),
      Promise.resolve(getAuthorityMetrics()),
      Promise.resolve(getAuthorityLayerHealth()),
      Promise.resolve(getPreApprovalMetrics()),
      getAuthorityAuditStats(days),
      getAuthorityAuditEntries({ limit: 20 }),
    ]);

    return {
      // Overall health status
      overallHealth: {
        status: transportStatus.enabled && authorityHealth.enabled ? 'healthy' :
          !transportStatus.enabled && authorityHealth.internalReachable ? 'degraded' :
          'critical',
        transportMode: transportStatus.mode,
        externalReachable: authorityHealth.externalReachable,
        internalReachable: authorityHealth.internalReachable,
      },

      // Key metrics (for dashboard cards)
      keyMetrics: {
        totalDecisions: dbStats.totalDecisions,
        externalSuccessRate: Math.round(dbStats.externalSuccessRate * 10000) / 100,
        avgLatencyMs: dbStats.avgLatencyMs,
        preApprovalRate: preApprovalMetrics.preApprovalsRequested > 0
          ? Math.round((preApprovalMetrics.preApprovalsGranted / preApprovalMetrics.preApprovalsRequested) * 10000) / 100
          : 0,
        failClosedEvents: authorityMetrics.failClosedEvents + preApprovalMetrics.failClosedEvents,
        blockedDecisions: dbStats.blockedDecisions,
      },

      // Recent activity
      recentActivity: recentEntries.slice(0, 10).map((entry: AuthorityAuditEntry) => ({
        surfaceType: entry.surfaceType,
        regulated: entry.regulated,
        approved: entry.finalApproved,
        latencyMs: entry.totalLatencyMs,
        createdAt: entry.createdAt,
      })),

      periodDays: days,
    };
  });

// ============================================================================
// ROUTER COMPOSITION
// ============================================================================

export const governanceDashboardRouter = router({
  /** Panel 1: Transport health, performance, and circuit breaker state */
  transportHealth: transportHealthProcedure,

  /** Panel 2: Authority decisions, merge strategies, and audit trail */
  authorityDecisions: authorityDecisionsProcedure,

  /** Panel 3: Regulated flow, pre-approval, and fail-closed events */
  regulatedFlow: regulatedFlowProcedure,

  /** Prometheus-format metrics export */
  prometheus: prometheusExportProcedure,

  /** Combined overview for dashboard landing (all 3 panels summary) */
  overview: overviewProcedure,
});

